"""Incremental reference simulator for generating event streams."""
class Sim:
    def __init__(self,P,R,D,inp,slotsn,window):
        self.P=P; self.R=R; self.D=D; self.inp=inp
        self.slotsn=slotsn; self.window=window
        self.buf=[None]*slotsn
        self.sent=[0]*P; self.acked=[0]*P; self.upnext=[0]*P; self.floor=0
        self.received=[[] for _ in range(P)]
        self.pend={}; self.created=0
    def pending(self):
        return sorted(self.pend.keys())
    def propose(self):
        """yield candidate event drafts"""
        opts=["deliver","send","retry","drop","duplicate"]
        return opts
    def tick(self, ev):
        """apply event; return list of created ids"""
        k=ev[0]; cr=[]
        if k=="send":
            r,q=ev[1],ev[2]
            hi=min(self.R, self.sent[r]+self.window)
            if self.sent[r]<=q<hi:
                pid=self.mk("up",r,q,[x for x in self.inp[r][q]]); cr.append(pid)
        elif k=="retry":
            ents=sorted([e.seq for e in self.buf if e is not None and len(e.ranks)==self.P and e.seq>=self.acked[ev[1]]])
            for q in ents:
                for e in self.buf:
                    if e is not None and e.seq==q:
                        cr.append(self.mk("down",ev[1],q,[x for x in e.sum]))
        elif k=="drop":
            if ev[1] in self.pend: del self.pend[ev[1]]
        elif k=="duplicate":
            p=self.pend.get(ev[1])
            if p is not None:
                cr.append(self.mk(p["kind"],p["rank"],p["seq"],
                                  [x for x in p["value"]] if isinstance(p["value"],list) else p["value"]))
        else:
            p=self.pend.pop(ev[1],None)
            if p is not None:
                k2=p["kind"]; r=p["rank"]; q=p["seq"]
                if k2=="up":
                    if self.floor<=q<self.floor+self.slotsn:
                        i=q%self.slotsn; e=self.buf[i]
                        if e is None or e.seq!=q:
                            class Ent: pass
                            e=Ent(); e.seq=q; e.ranks=set(); e.sum=[0]*self.D
                            self.buf[i]=e
                        became=False
                        if r not in e.ranks:
                            for j in range(self.D): e.sum[j]+=p["value"][j]
                            e.ranks.add(r)
                            became = len(e.ranks)==self.P
                        n=self.upnext[r]
                        while True:
                            e2=self.buf[n%self.slotsn]
                            if e2 is not None and e2.seq==n and r in e2.ranks: n+=1
                            else: break
                        self.upnext[r]=n
                        cr.append(self.mk("uack",r,n,None))
                        if became:
                            for t in range(self.P):
                                cr.append(self.mk("down",t,q,[x for x in e.sum]))
                    else:
                        cr.append(self.mk("uack",r,self.upnext[r],None))
                elif k2=="uack":
                    if q>self.sent[r]: self.sent[r]=q
                elif k2=="down":
                    if q==len(self.received[r]): self.received[r].append([x for x in p["value"]])
                    cr.append(self.mk("dack",r,len(self.received[r]),None))
                else:
                    if q>self.acked[r]:
                        self.acked[r]=q
                        nf=min(self.acked)
                        if nf>self.floor:
                            self.floor=nf
                            for i in range(self.slotsn):
                                if self.buf[i] is not None and self.buf[i].seq<self.floor: self.buf[i]=None
        return cr
    def mk(self,kind,rank,seq,value):
        if len(self.pend)>=2000 or self.created>=199000: return None
        self.pend[self.created]=[kind,rank,seq,value]; self.created+=1
        return self.created-1
    def snapshot(self):
        slotlist=sorted([{"seq":e.seq,"ranks":sorted(e.ranks),"sum":list(e.sum)} for e in self.buf if e is not None], key=lambda z:z["seq"])
        pks=[{"id":i,"kind":self.pend[i][0],"rank":self.pend[i][1],"seq":self.pend[i][2],"value":self.pend[i][3]} for i in sorted(self.pend)]
        return {"hosts":[{"sent":self.sent[r],"received":[[x for x in v] for v in self.received[r]]} for r in range(self.P)],
                "floor":self.floor,"slots":slotlist,"packets":pks}
