import json,random,sys
sys.path.insert(0,'/app/tmp/fz')
from rp2 import Sim
src=open('/app/submission/main.py').read().replace("\nmain()\n","")
g={}; exec(compile(src,"m","exec"),g)
from rp import sim
seed=int(sys.argv[1]); trials=int(sys.argv[2])
random.seed(seed)
bad=0
for tr in range(trials):
    P=random.choice([1,2,3]); R=random.choice([2,3,4,6]); D=random.choice([0,1,1,2])
    inp=[[[random.randint(-4,4) for _ in range(D)] for _ in range(R)] for _ in range(P)]
    slotsn=random.randint(1,5); window=random.randint(1,slotsn)
    s=Sim(P,R,D,inp,slotsn,window)
    events=[]
    stalls=0
    while len(events)<random.randint(20,300):
        opts=[]
        pend=s.pending()
        if pend: 
            n=random.choice(pend)
            opts += [["deliver",n],["deliver",n],["drop",n],["duplicate",n],["deliver",n]]
        for r in range(P):
            hi=min(R, s.sent[r]+s.window)
            if s.sent[r] < hi:
                q=random.randrange(s.sent[r], hi)
                opts.append(["send",r,q])
        for r in range(P):
            opts.append(["retry",r])
        if not opts: break
        ev=random.choice(opts)
        s2=Sim(P,R,D,inp,slotsn,window)
        s2.buf=[x for x in s.buf]; s2.sent=list(s.sent); s2.received=[[list(v) for v in row] for row in s.received]
        events.append(ev)
        cx=s.tick(ev)
        if cx is None:
            events.pop()
            stalls+=1
            if stalls>5: break
        else:
            stalls=0
    req={"op":"replay","inputs":inp,"slots":slotsn,"window":window,"events":events}
    mine=g['handle'](json.loads(json.dumps(req)))
    ref=sim(P,R,D,inp,slotsn,window,events)
    if mine!=ref:
        bad+=1
        print(json.dumps(req))
        for a,b in zip(mine.get("events",[]),ref.get("events",[])):
            if a!=b: print("DIFF event", json.dumps(a), json.dumps(b))
        if mine.get("packets")!=ref.get("packets"): print("PACKET DIFF")
        if mine.get("hosts")!=ref.get("hosts"): print("host mine",mine.get("hosts"),"ref",ref.get("hosts"))
        if bad>2: break
print("done bad=",bad,trials)
